<?php require 'config/database.php';session_start();if(isset($_SESSION['user_id'])){header('Location: '.($_SESSION['role']==='admin'?'admin/dashboard.php':'student/dashboard.php'));exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=strtoupper(trim($_POST['user_id']));$st=$pdo->prepare('SELECT * FROM users WHERE user_id=? AND status=1');$st->execute([$id]);$u=$st->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user_id']=$u['id'];$_SESSION['role']=$u['role'];$_SESSION['name']=$u['name'];$_SESSION['student_id']=$u['student_id'];header('Location: '.($u['role']==='admin'?'admin/dashboard.php':'student/dashboard.php'));exit;}$err='Invalid User ID or password.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Portal Login</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="login"><div class="loginbox"><h1>Student Portal</h1><p class="muted">Student and admin management system.</p><?php if($err):?><div class="alert error"><?=$err?></div><?php endif;?><form method="post"><div class="form"><label>User ID</label><input name="user_id" required></div><div class="form"><label>Password</label><input type="password" name="password" required></div><button class="btn">Login</button></form><div class="alert" style="margin-top:16px">Student: <b>STU001</b> / <b>student123</b><br>Admin: <b>ADMIN</b> / <b>admin123</b></div></div></div></body></html>
